import React from 'react';
import { motion } from 'framer-motion';
import './LoadingScreen.css';

export default function LoadingScreen() {
  return (
    <div className="ls">
      <div className="ls__bg" />
      <motion.div className="ls__content"
        initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.5 }}>
        <motion.span className="ls__brand"
          initial={{ letterSpacing: '20px', opacity: 0 }}
          animate={{ letterSpacing: '8px', opacity: 1 }}
          transition={{ duration: 1.2, ease: [0.77,0,0.175,1] }}>
          LUXURY AUTO
        </motion.span>
        <div className="ls__bar"><motion.div className="ls__fill" animate={{ x: ['-100%','200%'] }} transition={{ duration: 1.5, ease: [0.77,0,0.175,1], repeat: Infinity }} /></div>
        <span className="ls__sub">Mercedes · Porsche</span>
      </motion.div>
    </div>
  );
}
